# ModelForms 🔗

Automatically create forms from models!

## Basic ModelForm

```python
from django import forms
from .models import Article

class ArticleForm(forms.ModelForm):
    class Meta:
        model = Article
        fields = ['title', 'content', 'category', 'tags']
        # Or include all: fields = '__all__'
        # Or exclude: exclude = ['author', 'created']
```

## Customizing ModelForm

```python
class ArticleForm(forms.ModelForm):
    class Meta:
        model = Article
        fields = ['title', 'content', 'status']

        labels = {
            'title': 'Article Title',
            'content': 'Article Body',
        }

        widgets = {
            'title': forms.TextInput(attrs={'class': 'form-control'}),
            'content': forms.Textarea(attrs={'rows': 10, 'class': 'form-control'}),
            'status': forms.Select(attrs={'class': 'form-select'}),
        }

        help_texts = {
            'title': 'Enter a descriptive title',
        }

        error_messages = {
            'title': {
                'required': 'Please enter a title',
                'max_length': 'Title is too long',
            },
        }
```

# Using ModelForms 💾

## Create View

```python
def article_create(request):
    if request.method == 'POST':
        form = ArticleForm(request.POST, request.FILES)  # Include FILES for uploads
        if form.is_valid():
            article = form.save()  # Creates and saves to database!
            return redirect('article_detail', pk=article.pk)
    else:
        form = ArticleForm()

    return render(request, 'articles/form.html', {'form': form})
```

## Update View

```python
def article_update(request, pk):
    article = get_object_or_404(Article, pk=pk)

    if request.method == 'POST':
        form = ArticleForm(request.POST, instance=article)  # Pass existing instance!
        if form.is_valid():
            form.save()  # Updates existing record
            return redirect('article_detail', pk=article.pk)
    else:
        form = ArticleForm(instance=article)  # Pre-populate with existing data

    return render(request, 'articles/form.html', {'form': form})
```

## Saving with Additional Data

```python
def article_create(request):
    if request.method == 'POST':
        form = ArticleForm(request.POST)
        if form.is_valid():
            article = form.save(commit=False)  # Don't save yet!
            article.author = request.user      # Add extra data
            article.save()                     # Now save
            form.save_m2m()                    # Save many-to-many relationships
            return redirect('article_detail', pk=article.pk)
```

> 💡 **ModelForms are the recommended way to create/edit model instances!**
